'use strict';

const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const state = {
  page:'overview', invTab:'stockout', summary:null, financial:null,
  stockout:[], overstock:[], slow:[], anomalies:[], transfers:[],
  blockedCapital:[], revenueRisk:[], workspace:null, validatedDatasetId:null,
  copilot:null, stores:new Map()
};

const pageMeta = {
  overview:['Decision Overview','Priorities, scenarios and operating signals'],
  actions:['Action Center','Ranked operational priorities'],
  inventory:['Inventory','Stock risk, excess cover and slow-moving positions'],
  sales:['Sales Signals','Measured spikes and drops against baseline demand'],
  transfers:['Smart Transfers','Safe cross-store inventory rebalancing'],
  twin:['Decision Twin','Compare actions before approving them'],
  financial:['Financial Impact','Translate operating exposure into ₹ impact'],
  data:['Data Workspace','Review or switch the active analysis dataset']
};

function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function num(v,d=2){if(v===null||v===undefined||v===''||Number.isNaN(Number(v)))return 'Unknown';return Number(v).toLocaleString('en-IN',{minimumFractionDigits:0,maximumFractionDigits:d});}
function money(v){if(v===null||v===undefined||v===''||Number.isNaN(Number(v)))return 'Unknown';const n=Number(v),a=Math.abs(n);if(a>=1e7)return `₹${(n/1e7).toFixed(2)} Cr`;if(a>=1e5)return `₹${(n/1e5).toFixed(2)} L`;return `₹${n.toLocaleString('en-IN',{minimumFractionDigits:0,maximumFractionDigits:2})}`;}
function pct(v,d=1){return v===null||v===undefined?'Unknown':`${num(v,d)}%`;}
function badge(v){const raw=String(v??'unknown');const x=raw.toLowerCase().replace(/\s+/g,'-');return `<span class="status-inline ${esc(x)}"><span class="status-inline-dot"></span><span>${esc(raw.replace(/_/g,' '))}</span></span>`;}
function icon(name){const paths={revenue:'<path d="M7 4h10M7 8h10M9 4c5 0 5 8 0 8H7l9 8"/>',health:'<path d="M12 21s7-3.8 7-10V5l-7-2-7 2v6c0 6.2 7 10 7 10Z"/><path d="m9 12 2 2 4-4"/>',alert:'<path d="M12 3 2.8 19h18.4L12 3Z"/><path d="M12 9v4M12 17h.01"/>',transfer:'<path d="M7 7h12m-3-3 3 3-3 3M17 17H5m3-3-3 3 3 3"/>',capital:'<rect x="3" y="6" width="18" height="13" rx="2"/><path d="M16 10h3v5h-3a2.5 2.5 0 0 1 0-5ZM7 6l6-3 2 3"/>',signal:'<path d="M4 19V5M4 19h16m-13-4 4-5 3 3 5-7"/>',database:'<ellipse cx="12" cy="5" rx="7" ry="3"/><path d="M5 5v6c0 1.7 3.1 3 7 3s7-1.3 7-3V5M5 11v6c0 1.7 3.1 3 7 3s7-1.3 7-3v-6"/>',box:'<path d="m4 7 8-4 8 4-8 4-8-4Z"/><path d="M4 7v10l8 4 8-4V7M12 11v10"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.alert}</svg>`;}
function metricCard(label,value,foot,type='info',ico='revenue'){return `<article class="metric-card ${type}"><div class="metric-top"><span class="metric-label">${esc(label)}</span><span class="metric-icon">${icon(ico)}</span></div><div class="metric-value">${esc(value)}</div><div class="metric-foot">${esc(foot||'')}</div></article>`;}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2300);}
async function api(path,opts={}){const res=await fetch(path,{headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});let body=null;try{body=await res.json();}catch{body={};}if(!res.ok)throw new Error(body.detail||body.error||`Request failed (${res.status})`);return body;}


const FLOW = {
  authKey:'retailiq.authenticated',
  datasetKey:'retailiq.datasetReady',
  userKey:'retailiq.user',
  loading:false
};

function setFlowVisibility(mode){
  const auth=$('#auth-screen'), onboarding=$('#onboarding-screen'), shell=$('.app-shell');
  if(auth) auth.hidden=mode!=='login';
  if(onboarding) onboarding.hidden=mode!=='onboarding';
  if(shell) shell.classList.toggle('flow-hidden',mode!=='workspace');
  document.body.classList.toggle('workspace-open',mode==='workspace');
}

function currentUser(){return sessionStorage.getItem(FLOW.userKey)||'manager@retailiq.local';}
function updateSignedUser(){const el=$('#signed-user');if(el)el.textContent=currentUser().split('@')[0];}

function showLogin(){
  closeCopilot?.();
  setFlowVisibility('login');
  const err=$('#login-error');if(err)err.textContent='';
  setTimeout(()=>$('#login-email')?.focus(),50);
}

async function showOnboarding(fromWorkspace=false){
  closeCopilot?.();
  setFlowVisibility('onboarding');
  const back=$('#onboarding-back');if(back)back.hidden=!fromWorkspace;
  await loadWorkspace();
  window.scrollTo({top:0,behavior:'instant'});
}

async function enterWorkspace({refresh=true}={}){
  setFlowVisibility('workspace');
  updateSignedUser();
  setPage('overview');
  if(refresh && !FLOW.loading){
    FLOW.loading=true;
    try{
      await Promise.all([loadWorkspace(),loadAll(),loadCopilotStatus()]);
      await runTwin();
    }finally{FLOW.loading=false;}
  }
}

function signOut(){
  sessionStorage.removeItem(FLOW.authKey);
  sessionStorage.removeItem(FLOW.userKey);
  sessionStorage.removeItem(FLOW.datasetKey);
  showLogin();
}

function markDatasetReady(kind){sessionStorage.setItem(FLOW.datasetKey,kind||'selected');}
function datasetIsReady(){return Boolean(sessionStorage.getItem(FLOW.datasetKey));}

function setPage(name){if(!pageMeta[name])name='overview';state.page=name;$$('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${name}`));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===name));$('#page-title').textContent=pageMeta[name][0];$('#page-subtitle').textContent=pageMeta[name][1];closeSidebar();window.scrollTo({top:0,behavior:'smooth'});}
$$('[data-page]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
$$('[data-goto]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.goto)));
function openSidebar(){$('#sidebar').classList.add('open');$('#sidebar-backdrop').classList.add('open');}
function closeSidebar(){$('#sidebar').classList.remove('open');$('#sidebar-backdrop').classList.remove('open');}
$('#menu-btn').addEventListener('click',openSidebar);$('#sidebar-close').addEventListener('click',closeSidebar);$('#sidebar-backdrop').addEventListener('click',closeSidebar);

function renderOverview(){const s=state.summary,f=state.financial;if(!s||!f)return;$('#analysis-date').textContent=s.analysis_date||'—';const risk=s.inventory.stockout_risk||{};const critical=Number(risk.critical||0),high=Number(risk.high||0),health=s.inventory.average_health_score;$('#overview-metrics').innerHTML=[
  metricCard('30-day revenue',money(s.sales.revenue),`${num(s.sales.units_sold,0)} units sold`,'info','revenue'),
  metricCard('Inventory health',health==null?'Unknown':pct(health,1),'Average deterministic health score','good','health'),
  metricCard('Critical risks',num(critical,0),`${num(high,0)} high-risk positions`,'critical','alert'),
  metricCard('Revenue at risk',money(f.stockout_exposure.revenue_at_risk),`${num(f.stockout_exposure.products,0)} exposed positions`,'warn','signal'),
  metricCard('Transfer opportunities',num(f.smart_transfer.recommendations,0),`${money(f.smart_transfer.estimated_revenue_protected)} revenue protected`,'good','transfer'),
  metricCard('Blocked capital',money(f.overstock_exposure.blocked_capital_at_cost),`${num(f.overstock_exposure.products,0)} excess positions`,'warn','capital')
].join('');
  renderPriorityPane(s.attention||[]);renderRiskVisual(risk);renderStoreAttention(s.attention||[]);renderOverviewSignals();renderOverviewTransfers();renderActionCenter();
}
function renderAttention(target,items,compact=false){if(!items.length){target.innerHTML='<div class="empty-state">No priority issues found.</div>';return;}target.innerHTML=items.map(i=>{const metric=i.headline_metric_name==='percentage_change'?`${i.headline_metric>=0?'+':''}${num(i.headline_metric,1)}%`:i.headline_metric==null?'Unknown':`${num(i.headline_metric)} days`;return `<div class="attention-row">${badge(i.severity)}<div><div class="product">${esc(i.product_name)}</div><div class="store">${esc(i.product_id)}</div></div><div class="store">${esc(i.store_name)}</div><div class="metric">${esc(metric)}</div><div class="reason">${esc(i.reason)}</div></div>`;}).join('');if(compact)target.classList.add('compact');}
function renderPriorityPane(items){const target=$('#overview-attention');if(!target)return;if(!items.length){target.innerHTML='<div class="empty-state">No priority items right now.</div>';return;}target.innerHTML=items.slice(0,7).map(i=>{const sev=String(i.severity||'unknown').toLowerCase().replace(/\s+/g,'-');const metric=i.headline_metric_name==='percentage_change'?`${i.headline_metric>=0?'+':''}${num(i.headline_metric,1)}%`:i.headline_metric==null?'Unknown':`${num(i.headline_metric)} days`;const issue=i.type==='stockout'?'Stockout risk':i.type==='overstock'?'Excess inventory':'Sales signal';return `<div class="priority-row"><span class="priority-line ${esc(sev)}" aria-hidden="true"></span><div class="priority-main"><div class="priority-title">${esc(i.product_name)}</div><div class="priority-meta">${esc(shortStore(i.store_name))} · ${esc(issue)}</div><div class="priority-reason">${esc(i.reason)}</div></div><div class="priority-value">${esc(metric)}</div></div>`;}).join('');}
function renderRiskVisual(risk){const keys=['critical','high','watch','low','unknown'],colors={critical:'#b42318',high:'#d97706',watch:'#d4a017',low:'#17875b',unknown:'#98a2b3'},vals=keys.map(k=>Number(risk[k]||0)),total=vals.reduce((a,b)=>a+b,0)||1;let offset=0;const circles=keys.map((k,idx)=>{const val=vals[idx],len=val/total*100,c=`<circle cx="63" cy="63" r="48" pathLength="100" stroke="${colors[k]}" stroke-dasharray="${len} ${100-len}" stroke-dashoffset="${-offset}"/>`;offset+=len;return c;}).join('');$('#risk-visual').innerHTML=`<div class="donut"><svg viewBox="0 0 126 126" role="img" aria-label="Inventory risk distribution"><circle class="base" cx="63" cy="63" r="48" pathLength="100"/>${circles}</svg><div class="donut-center"><div><strong>${num(vals[0]+vals[1],0)}</strong><span>need attention</span></div></div></div><div class="risk-legend">${keys.map((k,i)=>`<div class="legend-row"><span class="legend-dot" style="background:${colors[k]}"></span><span>${esc(k[0].toUpperCase()+k.slice(1))}</span><strong>${num(vals[i],0)}</strong></div>`).join('')}</div>`;}
function renderStoreAttention(items){const counts={};items.forEach(i=>{const n=i.store_name||i.store_id||'Unknown';counts[n]=(counts[n]||0)+1;});renderBars($('#store-attention-chart'),Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([label,value])=>({label,value,display:`${value} issues`})));}
function renderOverviewSignals(){const top=state.anomalies.slice(0,4);$('#overview-signals').innerHTML=top.length?top.map(i=>`<div class="mini-signal"><div><strong>${esc(i.product_name)}</strong><span>${esc(shortStore(i.store_name))} · ${esc(i.anomaly_type)}</span></div><div class="${i.percentage_change>=0?'change-up':'change-down'}">${i.percentage_change>=0?'+':''}${num(i.percentage_change,1)}%</div></div>`).join(''):'<div class="empty-state">No unusual sales signals detected.</div>';}
function renderOverviewTransfers(){const target=$('#overview-transfers');if(!target)return;const top=state.transfers.slice(0,4);target.innerHTML=top.length?top.map(i=>`<div class="mini-transfer"><div><strong>${esc(i.product_name)}</strong><span>${esc(shortStore(i.recommended_source_store_name))} → ${esc(shortStore(i.recipient_store_name))}</span></div><div class="mini-transfer-value">${num(i.recommended_transfer_quantity,0)} units</div></div>`).join(''):'<div class="empty-state">No safe transfer recommendations.</div>';}
function renderBars(target,items,formatter=v=>String(v)){if(!target)return;if(!items.length){target.innerHTML='<div class="empty-state">No data available.</div>';return;}const max=Math.max(...items.map(i=>Number(i.value)||0),1);target.innerHTML=items.map(i=>`<div class="bar-row"><div class="bar-label" title="${esc(i.label)}">${esc(i.label)}</div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(2,(Number(i.value)||0)/max*100)}%"></div></div><div class="bar-value">${esc(i.display??formatter(i.value))}</div></div>`).join('');}
function renderActionCenter(){const items=state.summary?.attention||[];$('#action-count').textContent=num(items.length,0);$('#action-body').innerHTML=items.map(i=>{const metric=i.headline_metric_name==='percentage_change'?`${i.headline_metric>=0?'+':''}${num(i.headline_metric,1)}%`:i.headline_metric==null?'Unknown':`${num(i.headline_metric)} days`;const issue=i.type==='stockout'?'Stockout risk':i.type==='overstock'?'Excess inventory':'Sales anomaly';return `<tr><td>${badge(i.severity)}</td><td><strong>${esc(i.product_name)}</strong><span class="cell-sub">${esc(i.product_id)}</span></td><td>${esc(i.store_name)}</td><td>${esc(issue)}</td><td class="number">${esc(metric)}</td><td>${esc(i.reason)}</td></tr>`;}).join('')||'<tr><td colspan="6" class="empty-cell">No priority actions found.</td></tr>';}

function populateInventoryFilters(){const stores=new Map();[...state.stockout,...state.overstock,...state.slow].forEach(i=>{if(i.store_id)stores.set(i.store_id,i.store_name||i.store_id);});const sel=$('#inventory-store-filter');sel.innerHTML='<option value="">All stores</option>'+[...stores.entries()].map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('');renderInventoryRiskOptions();}
function renderInventoryRiskOptions(){const tab=state.invTab,sel=$('#inventory-risk-filter');const values=tab==='stockout'?['critical','high','watch','low','unknown']:tab==='overstock'?['severe','overstock','unknown']:['slow_mover'];sel.innerHTML='<option value="">All statuses</option>'+values.map(v=>`<option value="${esc(v)}">${esc(v.replace('_',' '))}</option>`).join('');}
function inventoryItems(){const arr=state.invTab==='stockout'?state.stockout:state.invTab==='overstock'?state.overstock:state.slow;const q=$('#inventory-search').value.trim().toLowerCase(),store=$('#inventory-store-filter').value,risk=$('#inventory-risk-filter').value;return arr.filter(i=>{const text=`${i.product_name||''} ${i.product_id||''} ${i.store_name||''}`.toLowerCase();const status=state.invTab==='stockout'?i.risk:state.invTab==='overstock'?i.severity:'slow_mover';return(!q||text.includes(q))&&(!store||i.store_id===store)&&(!risk||status===risk);});}
function coverVisual(days,lead){if(days==null)return '<span class="cell-sub">No meaningful cover value</span>';const max=Math.max(Number(days)||0,Number(lead)||0,1);return `<div class="cover-bars"><div class="cover-line"><span>Cover</span><div class="bar-track"><div class="bar-fill" style="width:${Math.min(100,Number(days)/max*100)}%"></div></div><b>${num(days,1)}d</b></div>${lead!=null?`<div class="cover-line lead"><span>Lead</span><div class="bar-track"><div class="bar-fill" style="width:${Math.min(100,Number(lead)/max*100)}%"></div></div><b>${num(lead,1)}d</b></div>`:''}</div>`;}
function renderInventory(){const items=inventoryItems(),head=$('#inventory-head'),body=$('#inventory-body');if(state.invTab==='stockout'){head.innerHTML='<tr><th>Product</th><th>Store</th><th>Stock</th><th>Demand/day</th><th>Cover vs lead time</th><th>Risk</th><th>Reorder</th></tr>';body.innerHTML=items.map(i=>`<tr><td><strong>${esc(i.product_name)}</strong><span class="cell-sub">${esc(i.product_id)}</span></td><td>${esc(i.store_name)}</td><td class="number">${num(i.current_stock,0)}</td><td class="number">${num(i.avg_daily_sales)}</td><td class="cover-cell">${coverVisual(i.days_cover,i.lead_time_days)}</td><td>${badge(i.risk)}</td><td class="number">${i.recommended_reorder_qty==null?'Withheld':num(i.recommended_reorder_qty,0)}</td></tr>`).join('');}
  else if(state.invTab==='overstock'){head.innerHTML='<tr><th>Product</th><th>Store</th><th>Stock</th><th>30-day sales</th><th>Days cover</th><th>Severity</th><th>Reason</th></tr>';body.innerHTML=items.map(i=>`<tr><td><strong>${esc(i.product_name)}</strong><span class="cell-sub">${esc(i.product_id)}</span></td><td>${esc(i.store_name)}</td><td class="number">${num(i.current_stock,0)}</td><td class="number">${num(i.units_sold,0)}</td><td class="number">${i.days_cover==null?'Not meaningful':`${num(i.days_cover,1)} d`}</td><td>${badge(i.severity)}</td><td>${esc(i.reason)}</td></tr>`).join('');}
  else{head.innerHTML='<tr><th>Product</th><th>Store</th><th>Stock</th><th>Units sold</th><th>Days cover</th><th>Status</th><th>Reason</th></tr>';body.innerHTML=items.map(i=>`<tr><td><strong>${esc(i.product_name)}</strong><span class="cell-sub">${esc(i.product_id)}</span></td><td>${esc(i.store_name)}</td><td class="number">${num(i.current_stock,0)}</td><td class="number">${num(i.units_sold,0)}</td><td class="number">${i.days_cover==null?'Not meaningful':`${num(i.days_cover,1)} d`}</td><td>${badge('slow mover')}</td><td>${esc(i.reason)}</td></tr>`).join('');}
  if(!items.length)body.innerHTML=`<tr><td colspan="7" class="empty-cell">No matching inventory positions.</td></tr>`;
}
$$('#inventory-tabs .tab').forEach(b=>b.addEventListener('click',()=>{$$('#inventory-tabs .tab').forEach(x=>x.classList.toggle('active',x===b));state.invTab=b.dataset.inv;renderInventoryRiskOptions();renderInventory();}));['#inventory-search','#inventory-store-filter','#inventory-risk-filter'].forEach(s=>$(s).addEventListener(s==='#inventory-search'?'input':'change',renderInventory));

function renderSales(){const a=state.anomalies,spikes=a.filter(i=>i.anomaly_type==='spike').length,drops=a.filter(i=>i.anomaly_type==='drop').length;$('#signal-summary').innerHTML=`<div class="signal-card"><div class="signal-mark up">↑</div><div><strong>${spikes}</strong><span>Demand spikes detected</span></div></div><div class="signal-card"><div class="signal-mark down">↓</div><div><strong>${drops}</strong><span>Demand drops detected</span></div></div>`;$('#sales-body').innerHTML=a.map(i=>{const base=Number(i.baseline_avg_daily_sales)||0,recent=Number(i.recent_avg_daily_sales)||0,max=Math.max(base,recent,1);return `<tr><td><strong>${esc(i.product_name)}</strong><span class="cell-sub">${esc(i.product_id)}</span></td><td>${esc(i.store_name)}</td><td>${badge(i.anomaly_type)}</td><td class="number">${num(recent)}</td><td class="number">${num(base)}</td><td class="number ${i.percentage_change>=0?'change-up':'change-down'}">${i.percentage_change>=0?'+':''}${num(i.percentage_change,1)}%</td><td><div class="comparison-mini" title="Baseline versus recent average"><div style="height:${base/max*100}%"></div><div class="recent" style="height:${recent/max*100}%"></div></div></td></tr>`;}).join('')||'<tr><td colspan="7" class="empty-cell">No sales anomalies detected.</td></tr>';}
function renderTransfers(){const list=state.transfers;$('#transfer-list').innerHTML=list.map(i=>`<article class="transfer-card"><div class="panel-head"><div><p class="section-kicker">${esc(i.product_id)} · ${esc(i.category||'')}</p><h3>${esc(i.product_name)}</h3></div>${badge(i.recipient_risk)}</div><div class="transfer-route"><div class="store-node"><div class="node-label">Source</div><strong>${esc(i.recommended_source_store_name)}</strong><span>Donor cover after: ${num(i.donor_after_days_cover)} days</span></div><div class="route-mid"><span>${num(i.recommended_transfer_quantity,0)} units</span><div class="route-line"></div><span>${money(i.estimated_transfer_cost)}</span></div><div class="store-node"><div class="node-label">Recipient</div><strong>${esc(i.recipient_store_name)}</strong><span>${num(i.recipient_current_stock,0)} units · ${num(i.recipient_days_cover)} days cover</span></div></div><div class="transfer-meta"><span class="meta-chip">Move<strong>${num(i.recommended_transfer_quantity,0)} units</strong></span><span class="meta-chip">Recipient after<strong>${num(i.recipient_after_days_cover)} d</strong></span><span class="meta-chip">Donor after<strong>${num(i.donor_after_days_cover)} d</strong></span><span class="meta-chip">Purchase deferred<strong>${money(i.near_term_purchase_deferred)}</strong></span></div></article>`).join('')||'<div class="panel empty-state">No safe transfer recommendations.</div>';}

function renderOverviewDecision(r){const target=$('#overview-decision');if(!target)return;if(!r||r.status!=='ok'||!Array.isArray(r.scenarios)){target.innerHTML='<div class="empty-state">Decision comparison is unavailable for the default scenario.</div>';return;}const noAction=r.scenarios.find(x=>x.scenario_id==='no_action')||r.scenarios[0];const recId=r.comparison?.recommended_scenario_id;const rec=r.scenarios.find(x=>x.scenario_id===recId)||r.scenarios.find(x=>x.scenario_id!=='no_action')||r.scenarios[0];const service=n=>Math.max(0,Math.min(100,Number(n)||0));target.innerHTML=`<div class="decision-quick-grid"><div class="decision-quick-card"><div class="decision-quick-label"><span>No Action</span>${badge(r.current_state?.risk||'unknown')}</div><div class="decision-quick-title">${num(noAction.service_level_pct,1)}% service level</div><div class="decision-quick-metrics"><div class="decision-mini-metric"><span>Unserved</span><strong>${num(noAction.unserved_units,0)} units</strong></div><div class="decision-mini-metric"><span>Operational loss</span><strong>${money(noAction.estimated_operational_loss)}</strong></div></div><div class="decision-quick-footer"><span>Service</span><div class="decision-progress"><span style="width:${service(noAction.service_level_pct)}%"></span></div></div></div><div class="decision-arrow"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14"/><path d="m15 8 4 4-4 4"/></svg></div><div class="decision-quick-card recommended"><div class="decision-quick-label"><span>Recommended</span><span class="status-inline low"><span class="status-inline-dot"></span><span>${esc(rec.label||'Scenario')}</span></span></div><div class="decision-quick-title">${esc(r.comparison?.recommendation||rec.label||'Recommended scenario')}</div><div class="decision-quick-metrics"><div class="decision-mini-metric"><span>Service level</span><strong>${num(rec.service_level_pct,1)}%</strong></div><div class="decision-mini-metric"><span>Operational loss</span><strong>${money(rec.estimated_operational_loss)}</strong></div></div><div class="decision-quick-footer"><span>Service</span><div class="decision-progress"><span style="width:${service(rec.service_level_pct)}%"></span></div></div></div></div>`;}

async function runTwin(){const store=$('#twin-store').value.trim(),product=$('#twin-product').value.trim(),h=Number($('#twin-horizon').value||14),m=Number($('#twin-demand').value||1),btn=$('#run-twin');btn.disabled=true;btn.textContent='Simulating…';try{const r=await api(`/api/simulation/compare?store_id=${encodeURIComponent(store)}&product_id=${encodeURIComponent(product)}&horizon_days=${h}&demand_multiplier=${m}`);renderTwin(r);}catch(e){toast(e.message);$('#scenario-grid').innerHTML=`<div class="panel empty-state">${esc(e.message)}</div>`;}finally{btn.disabled=false;btn.textContent='Run simulation';}}
function renderTwin(r){if(r.status!=='ok'){const msg=r.message||'Insufficient data for a reliable simulation.';renderOverviewDecision(r);$('#twin-current').innerHTML='';$('#scenario-bars').innerHTML='';$('#scenario-grid').innerHTML=`<div class="panel empty-state">${esc(msg)}</div>`;$('#twin-recommendation').innerHTML=`<h3>Simulation withheld</h3><p>${esc(msg)}</p>`;return;}renderOverviewDecision(r);const c=r.current_state,d=r.demand_assumption||{},m=Number(d.demand_multiplier??r.demand_multiplier??1),ass=$('#twin-assumption');if(Math.abs(m-1)>.0001){ass.classList.add('show');ass.textContent=`What-if assumption — not a forecast. Baseline demand ${num(d.baseline_avg_daily_sales)}/day × ${num(m)} = ${num(d.simulated_avg_daily_sales)}/day over ${num(d.horizon_days||r.horizon_days,0)} days.`;}else{ass.classList.remove('show');ass.textContent='';}$('#twin-current').innerHTML=[['Risk',c.risk],['Current stock',num(c.current_stock,0)],['Avg demand/day',num(c.avg_daily_sales)],['Days cover',num(c.days_cover)],['Reorder qty',c.recommended_reorder_qty==null?'Withheld':num(c.recommended_reorder_qty,0)]].map(([a,b])=>`<div class="state-pill"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('');const rec=r.comparison?.recommended_scenario_id,maxLoss=Math.max(...r.scenarios.map(s=>Number(s.estimated_operational_loss)||0),1);$('#scenario-bars').innerHTML=r.scenarios.map(s=>`<div class="scenario-bar-group"><div class="scenario-bar-label"><strong>${esc(s.label)}</strong><span>${s.scenario_id===rec?'Recommended':''}</span></div><div class="dual-bar"><div class="service"><div style="width:${Math.max(0,Math.min(100,s.service_level_pct||0))}%"></div></div><div class="loss"><div style="width:${(Number(s.estimated_operational_loss)||0)/maxLoss*100}%"></div></div></div><div class="scenario-bar-values"><strong>${num(s.service_level_pct,1)}% service</strong><span>${money(s.estimated_operational_loss)} loss</span></div></div>`).join('');$('#scenario-grid').innerHTML=r.scenarios.map(s=>`<article class="scenario-card ${s.scenario_id===rec?'recommended':''}">${s.scenario_id===rec?'<span class="rec-ribbon">Recommended</span>':''}<h3>${esc(s.label)}</h3><span class="sub">${num(s.horizon_days,0)}-day scenario</span><div class="service-meter"><div style="width:${Math.max(0,Math.min(100,s.service_level_pct||0))}%"></div></div><span class="sub">${num(s.service_level_pct,1)}% service level</span><div class="scenario-kpis"><div class="scenario-kpi"><span>Unserved</span><strong>${num(s.unserved_units,0)} units</strong></div><div class="scenario-kpi"><span>Ending stock</span><strong>${num(s.ending_stock,0)}</strong></div><div class="scenario-kpi"><span>Operational loss</span><strong>${money(s.estimated_operational_loss)}</strong></div><div class="scenario-kpi"><span>Cash committed</span><strong>${money(s.cash_committed)}</strong></div></div></article>`).join('');$('#twin-recommendation').innerHTML=`<p class="section-kicker">DETERMINISTIC RECOMMENDATION</p><h3>${esc(r.comparison?.recommendation||'Review scenarios')}</h3><p>${esc(r.comparison?.reason||'')} ${esc(r.comparison?.human_decision_note||'')}</p>`;}
$('#run-twin').addEventListener('click',runTwin);

function renderFinancial(){const f=state.financial;if(!f)return;$('#financial-metrics').innerHTML=[metricCard('Revenue at risk',money(f.stockout_exposure.revenue_at_risk),`${f.stockout_exposure.products} exposed positions`,'critical','alert'),metricCard('Gross margin risk',money(f.stockout_exposure.gross_margin_at_risk),'Potential margin exposure','warn','signal'),metricCard('Blocked capital',money(f.overstock_exposure.blocked_capital_at_cost),`${f.overstock_exposure.products} excess positions`,'warn','capital'),metricCard('Revenue protected',money(f.smart_transfer.estimated_revenue_protected),`${f.smart_transfer.recommendations} safe transfer options`,'good','transfer')].join('');$('#stockout-money').innerHTML=`<div class="money-row"><span>Revenue at risk</span><strong>${money(f.stockout_exposure.revenue_at_risk)}</strong></div><div class="money-row"><span>Gross margin at risk</span><strong>${money(f.stockout_exposure.gross_margin_at_risk)}</strong></div><div class="money-row"><span>Retail value of excess</span><strong>${money(f.overstock_exposure.retail_value_of_excess)}</strong></div>`;$('#transfer-money').innerHTML=`<div class="money-row"><span>Estimated transfer cost</span><strong>${money(f.smart_transfer.estimated_transfer_cost)}</strong></div><div class="money-row"><span>Gross margin protected</span><strong>${money(f.smart_transfer.estimated_gross_margin_protected)}</strong></div><div class="money-row"><span>Purchase cash deferred</span><strong>${money(f.smart_transfer.near_term_cash_purchase_deferred)}</strong></div><div class="money-row"><span>Net operational benefit</span><strong>${money(f.smart_transfer.estimated_net_operational_benefit)}</strong></div>`;$('#financial-disclaimer').textContent=f.disclaimer||'';renderBars($('#blocked-capital-chart'),state.blockedCapital.slice(0,6).map(i=>({label:`${i.product_name} · ${shortStore(i.store_name)}`,value:i.blocked_capital_at_cost,display:money(i.blocked_capital_at_cost)})));renderBars($('#revenue-risk-chart'),state.revenueRisk.slice(0,6).map(i=>({label:`${i.product_name} · ${shortStore(i.store_name)}`,value:i.revenue_at_risk,display:money(i.revenue_at_risk)})));}
function shortStore(name){return String(name||'').replace('RetailIQ ','').replace(' Central','').replace(' West','').replace(' City','');}

async function loadWorkspace(){try{const w=await api('/api/data/workspace');state.workspace=w;const a=w.active_dataset||{},kind=a.kind==='custom'?'Custom':'Demo';const ds=$('#dataset-name');if(ds)ds.textContent=kind;const side=$('#sidebar-dataset');if(side)side.textContent=`${kind} · ${a.name||'active dataset'}`;const title=$('#active-dataset-title');if(title)title.textContent=a.name||`${kind} dataset`;const catalogs=w.catalogs||{},stores=catalogs.stores||[],products=catalogs.products||[],storeInput=$('#twin-store'),productInput=$('#twin-product');if(storeInput&&stores.length&&!stores.some(x=>x.store_id===storeInput.value))storeInput.value=stores[0].store_id;if(productInput&&products.length&&!products.some(x=>x.product_id===productInput.value))productInput.value=products[0].product_id;const s=w.summary||{},cards=[metricCard('Stores',num(s.stores,0),'Current active dataset','info','database'),metricCard('Products',num(s.products,0),'Product catalog','info','box'),metricCard('Sales rows',num(s.sales_rows,0),'Sales observations','good','signal'),metricCard('Inventory rows',num(s.inventory_rows,0),'Inventory observations','good','box')].join('');const target=$('#data-summary-cards');if(target)target.innerHTML=cards;return w;}catch(e){const target=$('#data-summary-cards');if(target)target.innerHTML=`<div class="panel empty-state">Data Workspace unavailable: ${esc(e.message)}</div>`;return null;}}
async function readFiles(){const map=[['stores.csv','#file-stores'],['products.csv','#file-products'],['sales.csv','#file-sales'],['inventory.csv','#file-inventory']],files={};for(const [name,sel] of map){const input=$(sel),f=input?.files?.[0];if(!f)throw new Error(`Choose ${name}.`);files[name]=await f.text();}return files;}
$('#validate-data').addEventListener('click',async()=>{const btn=$('#validate-data');btn.disabled=true;btn.textContent='Validating…';try{const files=await readFiles(),r=await api('/api/data/validate',{method:'POST',body:JSON.stringify({files})});state.validatedDatasetId=r.dataset_id||null;renderValidation(r);$('#activate-data').disabled=!r.valid;}catch(e){renderValidation({valid:false,errors:[e.message],warnings:[],summary:{}});toast(e.message);}finally{btn.disabled=false;btn.textContent='Validate dataset';}});
function renderValidation(r){const status=$('#data-validation-status');if(status){status.textContent=r.valid?'Validated':'Needs attention';status.className=`status-badge ${r.valid?'valid':'critical'}`;}const lines=[];(r.errors||[]).forEach(x=>lines.push(`<div class="validation-item error">${esc(x)}</div>`));(r.warnings||[]).forEach(x=>lines.push(`<div class="validation-item warning">${esc(x)}</div>`));if(r.valid)lines.unshift('<div class="validation-item good"><strong>Validation passed.</strong> Review the sample rows, then activate this dataset.</div>');const results=$('#validation-results');if(results)results.innerHTML=lines.join('')||'<div class="empty-state">No validation messages.</div>';const sm=r.summary||{},summary=$('#onboarding-validation-summary');if(summary)summary.innerHTML=[['Stores',sm.stores],['Products',sm.products],['Sales rows',sm.sales_rows],['Inventory rows',sm.inventory_rows]].map(([label,value])=>`<div class="validation-stat"><span>${esc(label)}</span><strong>${num(value,0)}</strong></div>`).join('');renderPreview(r.preview||{});}
function renderPreview(preview){const parts=Object.entries(preview).map(([name,info])=>{const rows=info.rows||[],cols=info.columns||[];return `<div class="preview-section"><h4>${esc(name)}.csv</h4><div class="table-wrap"><table class="preview-table"><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${cols.map(c=>`<td>${esc(row[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;});$('#data-preview').innerHTML=parts.join('')||'<div class="empty-state">No preview rows available.</div>';}
$('#activate-data').addEventListener('click',async()=>{if(!state.validatedDatasetId)return;const btn=$('#activate-data');btn.disabled=true;btn.textContent='Activating…';try{await api('/api/data/activate',{method:'POST',body:JSON.stringify({dataset_id:state.validatedDatasetId})});state.validatedDatasetId=null;markDatasetReady('custom');toast('Retail dataset activated');await enterWorkspace({refresh:true});}catch(e){toast(e.message);btn.disabled=false;}finally{btn.textContent='Activate & open workspace';}});

$('#use-demo-data').addEventListener('click',async()=>{const btn=$('#use-demo-data');btn.disabled=true;try{await api('/api/data/reset',{method:'POST'});markDatasetReady('demo');toast('Demo dataset selected');await enterWorkspace({refresh:true});}catch(e){toast(e.message);}finally{btn.disabled=false;}});

async function resetWorkspaceToDemo(){try{await api('/api/data/reset',{method:'POST'});markDatasetReady('demo');state.validatedDatasetId=null;toast('Demo dataset selected');await Promise.all([loadWorkspace(),loadAll()]);await runTwin();}catch(e){toast(e.message);}}
$('#workspace-reset-demo')?.addEventListener('click',resetWorkspaceToDemo);
$('#change-dataset')?.addEventListener('click',()=>showOnboarding(true));
$('#change-dataset-secondary')?.addEventListener('click',()=>showOnboarding(true));
$('#onboarding-back')?.addEventListener('click',()=>enterWorkspace({refresh:false}));

function openCopilot(prefill=''){const d=$('#copilot-drawer');d.classList.add('open');$('#copilot-backdrop').classList.add('open');d.setAttribute('aria-hidden','false');$('#copilot-fab').setAttribute('aria-expanded','true');if(prefill){$('#copilot-input').value=prefill;}setTimeout(()=>$('#copilot-input').focus(),80);}
function closeCopilot(){const d=$('#copilot-drawer');d.classList.remove('open');$('#copilot-backdrop').classList.remove('open');d.setAttribute('aria-hidden','true');$('#copilot-fab').setAttribute('aria-expanded','false');}
$('#copilot-fab').addEventListener('click',()=>openCopilot());$('#copilot-close').addEventListener('click',closeCopilot);$('#copilot-backdrop').addEventListener('click',closeCopilot);document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeCopilot();closeSidebar();}});$$('[data-open-copilot]').forEach(b=>b.addEventListener('click',()=>openCopilot(b.dataset.openCopilot||'')));
function hideCopilotWelcome(){const w=$('#copilot-welcome');if(w)w.remove();}
function responseMeta(r){if(!r)return'';const mode=r.mode==='gemini_grounded'?'Grounded explanation':'Deterministic';const review=r.human_review_required?'Manager review':'Decision support';return `<div class="response-meta"><span class="response-chip"><span class="mini-dot"></span>${esc(mode)}</span><span class="response-chip ${r.human_review_required?'review':''}"><span class="mini-dot"></span>${esc(review)}</span></div>`;}
function addMessage(role,text,r=null){hideCopilotWelcome();const chat=$('#chat'),el=document.createElement('div');el.className=`message ${role}`;let structured='';if(role==='assistant'&&r)structured=structuredHtml(r);el.innerHTML=`<div class="avatar">${role==='user'?'YOU':'RQ'}</div><div class="bubble">${role==='assistant'?'<strong>RetailIQ</strong>':''}<p>${esc(text)}</p>${role==='assistant'?responseMeta(r):''}${structured}</div>`;chat.appendChild(el);chat.scrollTop=chat.scrollHeight;}
function genericFindings(findings){if(!findings.length)return'';const rows=findings.slice(0,4).map(x=>{const product=x.product_name||x.label||x.scenario_id||x.store_name||'Finding';const detail=x.reason||x.issue||x.risk||x.severity||'';return `<li><strong>${esc(product)}</strong>${detail?` — ${esc(detail)}`:''}</li>`;}).join('');return `<div class="structured-block"><h5>Key findings</h5><ul>${rows}</ul></div>`;}
function structuredHtml(r){const rec=r.recommendation||{},findings=Array.isArray(r.findings)?r.findings:[],next=Array.isArray(r.next_actions)?r.next_actions:[];let html='<div class="structured-response">';if(rec.action)html+=`<div class="structured-block recommendation"><h5>Recommended next step</h5><p><strong>${esc(rec.action)}</strong></p>${rec.reason?`<p>${esc(rec.reason)}</p>`:''}</div>`;if(findings.length&&['decision_compare','demand_shock'].includes(r.intent))html+=scenarioMini(findings,r);else html+=genericFindings(findings);if(next.length)html+=`<div class="structured-block"><h5>Next actions</h5><ul>${next.slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`;if(r.clarification_required&&Array.isArray(r.candidates)&&r.candidates.length)html+=`<div class="structured-block"><h5>Choose one</h5><p>${r.candidates.slice(0,5).map(c=>esc(c.name||c.product_name||c.store_name||c)).join(' · ')}</p></div>`;html+='</div>';return html;}
function scenarioMini(findings,r){const rows=findings.slice(0,3).map(s=>`<div class="detail-row"><span>${esc(s.label||s.scenario_id||'Scenario')}</span><code>${num(s.service_level_pct,1)}% service · ${num(s.unserved_units,0)} unserved</code></div>`).join('');return `<div class="structured-block"><h5>Scenario comparison</h5>${rows}</div>`;}
function renderCopilotDetails(r){const trace=r.trace||{},ev=(r.evidence||[]).slice(0,8),unknowns=r.unknowns||[],assumptions=r.assumptions||[];$('#copilot-details').innerHTML=`<details class="details-box"><summary>Evidence & unknowns</summary><div class="details-content">${ev.map(e=>`<div class="evidence-line">${esc(e.citation_id||'Evidence')} · ${esc(e.source||'local records')} · ${num((e.record_ids||[]).length,0)} record(s)</div>`).join('')||'<div class="evidence-line">No record citations returned for this response.</div>'}${unknowns.length?`<div class="evidence-line"><strong>Unknowns:</strong> ${esc(unknowns.join(', '))}</div>`:''}</div></details><details class="details-box"><summary>Decision trace</summary><div class="details-content"><div class="detail-row"><span>Intent</span><code>${esc(r.intent||'unknown')}</code></div><div class="detail-row"><span>Mode</span><code>${esc(r.mode||'unknown')}</code></div><div class="detail-row"><span>Tool</span><code>${esc(r.tool||trace.tool||'—')}</code></div><div class="detail-row"><span>Routing confidence</span><code>${esc(String(r.confidence?.routing??trace.routing_confidence??'—'))}</code></div><div class="detail-row"><span>Total latency</span><code>${esc(String(r.total_latency_ms??trace.total_latency_ms??'—'))} ms</code></div><div class="detail-row"><span>Human review</span><code>${r.human_review_required?'Required':'Not required'}</code></div>${assumptions.slice(0,3).map(a=>`<div class="evidence-line">Assumption: ${esc(a)}</div>`).join('')}</div></details>`;}
async function askCopilot(message){const input=$('#copilot-input'),lang=$('#copilot-language').value;addMessage('user',message);input.value='';input.disabled=true;const send=$('.send-btn');if(send)send.disabled=true;try{const r=await api('/api/copilot/query',{method:'POST',body:JSON.stringify({message,language:lang||null})});state.copilot=r;addMessage('assistant',r.answer||r.summary||'No answer returned.',r);renderCopilotDetails(r);}catch(e){addMessage('assistant',`I could not complete that request: ${e.message}`);toast(e.message);}finally{input.disabled=false;if(send)send.disabled=false;input.focus();}}
$('#copilot-form').addEventListener('submit',e=>{e.preventDefault();const m=$('#copilot-input').value.trim();if(m)askCopilot(m);});$$('#quick-prompts button').forEach(b=>b.addEventListener('click',()=>{openCopilot();askCopilot(b.querySelector('.prompt-copy')?.textContent||b.textContent.trim());}));
async function loadCopilotStatus(){try{const s=await api('/api/copilot/status');const e=$('#model-status');e.innerHTML=`<span class="grounding-dot" aria-hidden="true"></span><span>${s.gemini_configured?'Grounded explanations ready':'Deterministic decision support ready'}</span>`;e.title=s.model||'RetailIQ Copilot';e.classList.add('ready');}catch{const e=$('#model-status');e.innerHTML='<span class="grounding-dot" aria-hidden="true"></span><span>Deterministic decision support ready</span>';e.classList.add('ready');}}

$('#global-prompt-form').addEventListener('submit',e=>{e.preventDefault();const input=$('#global-prompt');const message=input.value.trim();if(!message)return;openCopilot();input.value='';askCopilot(message);});

async function loadAll(){const refresh=$('#refresh-btn');refresh.disabled=true;try{const [summary,financial,stockout,overstock,slow,anomalies,transfers,blocked,revenueRisk]=await Promise.all([api('/api/dashboard/summary'),api('/api/financial/summary'),api('/api/inventory/stockout-risk?limit=150'),api('/api/inventory/overstock?limit=150'),api('/api/inventory/slow-movers?limit=150'),api('/api/sales/anomalies?limit=150'),api('/api/transfers/recommendations?limit=50'),api('/api/financial/overstock-capital?limit=50'),api('/api/financial/revenue-risk?limit=50')]);state.summary=summary;state.financial=financial;state.stockout=stockout.items||[];state.overstock=overstock.items||[];state.slow=slow.items||[];state.anomalies=anomalies.items||[];state.transfers=transfers.items||[];state.blockedCapital=blocked.items||[];state.revenueRisk=revenueRisk.items||[];renderOverview();populateInventoryFilters();renderInventory();renderSales();renderTransfers();renderFinancial();$('#api-status').classList.add('online');$('#api-status').classList.remove('degraded');$('#api-status').innerHTML='<span class="status-dot"></span><span>Ready</span>';toast('Retail data refreshed');}catch(e){$('#api-status').classList.add('degraded');$('#api-status').classList.remove('online');$('#api-status').innerHTML='<span class="status-dot"></span><span>Degraded</span>';toast(e.message);}finally{refresh.disabled=false;}}
$('#refresh-btn').addEventListener('click',loadAll);

function wireFlow(){
  ['stores','products','sales','inventory'].forEach(name=>{
    const input=$(`#file-${name}`), label=$(`#file-name-${name}`), card=$(`[data-file-card="${name}"]`);
    input?.addEventListener('change',()=>{const f=input.files?.[0];if(label)label.textContent=f?f.name:'Choose file';card?.classList.toggle('selected',Boolean(f));state.validatedDatasetId=null;const activate=$('#activate-data');if(activate)activate.disabled=true;const status=$('#data-validation-status');if(status){status.textContent='Not validated';status.className='status-badge neutral';}});
  });
  $('#toggle-password')?.addEventListener('click',()=>{const input=$('#login-password'),btn=$('#toggle-password');const show=input.type==='password';input.type=show?'text':'password';btn.textContent=show?'Hide':'Show';});
  $('#login-form')?.addEventListener('submit',async e=>{e.preventDefault();const email=$('#login-email').value.trim(),password=$('#login-password').value;const err=$('#login-error');if(email!=='manager@retailiq.local'||password!=='retailiq2026'){err.textContent='Use the demo manager credentials shown below.';return;}err.textContent='';sessionStorage.setItem(FLOW.authKey,'1');sessionStorage.setItem(FLOW.userKey,email);updateSignedUser();if(datasetIsReady())await enterWorkspace({refresh:true});else await showOnboarding(false);});
  $('#logout-btn')?.addEventListener('click',signOut);
  $('#onboarding-logout')?.addEventListener('click',signOut);
}

(async function boot(){
  wireFlow();
  if(sessionStorage.getItem(FLOW.authKey)!=='1'){showLogin();return;}
  updateSignedUser();
  if(!datasetIsReady()){await showOnboarding(false);return;}
  await enterWorkspace({refresh:true});
})();
